<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';

import {
  collectEncounteredCharacters,
  isWorldbookCharacterEntryName,
  parseWorldbookCharacterDisplayName,
