  type EncounteredCharacterRecord,
} from '../char_info_shared/characterEntryLibrary';
import { DEFAULT_CHAR_INFO_THEME_MODE, managerThemeClass, type CharInfoThemeMode } from '../char_info_shared/managerTheme';
