  min-height: 0;
  margin: auto;
  padding: clamp(28px, 5vw, 58px);
  overflow-y: auto;
  gap: 28px;
}

.mode-selection-hero {
  display: grid;
  max-width: 720px;
  gap: 8px;
}

.mode-eyebrow {
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.mode-selection-hero h2,
.flash-mode-heading h2 {
  margin: 0;
  color: var(--text);
  font-size: clamp(24px, 4vw, 36px);
  line-height: 1.18;
}

.mode-selection-hero > strong {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mode-selection-hero p,
.flash-mode-heading p {
  max-width: 700px;
  margin: 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.7;
}

.mode-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.mode-choice-card {
  --mode-accent: var(--primary);
  --mode-accent-rgb: var(--ci-primary-rgb);

  position: relative;
  display: grid;
  min-width: 0;
  min-height: 206px;
  padding: 0;
  overflow: visible;
  grid-template-areas:
    'stub copy'
    'stub action';
  grid-template-columns: 88px minmax(0, 1fr);
  grid-template-rows: 1fr auto;
  color: var(--text);
  text-align: left;
  background:
    radial-gradient(circle at 100% 0, rgb(var(--mode-accent-rgb) / 13%), transparent 48%),
    linear-gradient(145deg, rgb(var(--mode-accent-rgb) / 7%), var(--surface) 62%);
  border: 1px solid rgb(var(--mode-accent-rgb) / 32%);
  border-radius: 20px;
  box-shadow:
    0 12px 28px rgb(0 0 0 / 16%),
    inset 0 1px 0 rgb(255 255 255 / 4%);
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.mode-choice-card.flash {
  --mode-accent: #e1ad5d;
  --mode-accent-rgb: 225 173 93;
}

.mode-choice-card.pro {
  --mode-accent: #8fa9ed;
  --mode-accent-rgb: 143 169 237;
}

.manager-root.char-info-theme-light .mode-choice-card.flash {
  --mode-accent: #9b641d;
  --mode-accent-rgb: 190 127 45;
}

.manager-root.char-info-theme-light .mode-choice-card.pro {
  --mode-accent: #526fbd;
  --mode-accent-rgb: 82 111 189;
}

.mode-choice-card:hover:not(:disabled),
.mode-choice-card:focus-visible:not(:disabled) {
  border-color: rgb(var(--mode-accent-rgb) / 64%);
  box-shadow:
    0 16px 38px rgb(0 0 0 / 23%),
    0 0 0 1px rgb(var(--mode-accent-rgb) / 10%);
  transform: translateY(-2px);
  outline: none;
}

.mode-choice-card:focus-visible:not(:disabled) {
  outline: 2px solid rgb(var(--mode-accent-rgb) / 74%);
  outline-offset: 3px;
}

.mode-choice-card:disabled {
  opacity: 0.55;
  cursor: wait;
}

.mode-choice-stub {
  position: relative;
  display: grid;
  min-height: 100%;
  padding: 18px 10px;
  grid-area: stub;
  place-items: center;
  align-content: center;
  gap: 12px;
  color: var(--mode-accent);
  background: linear-gradient(180deg, rgb(var(--mode-accent-rgb) / 20%), rgb(var(--mode-accent-rgb) / 8%));
  border-right: 1px dashed rgb(var(--mode-accent-rgb) / 36%);
  border-radius: 19px 0 0 19px;
}

.mode-choice-stub::before,
.mode-choice-stub::after {
  position: absolute;
  right: -9px;
  width: 16px;
  height: 16px;
  content: '';
  background: var(--bg);
  border: 1px solid rgb(var(--mode-accent-rgb) / 28%);
  border-radius: 50%;
}

.mode-choice-stub::before {
  top: -9px;
}

.mode-choice-stub::after {
  bottom: -9px;
}

.mode-choice-ticket-label {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  opacity: 0.72;
}

.mode-choice-icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  color: var(--mode-accent);
  background: rgb(var(--mode-accent-rgb) / 12%);
  border: 1px solid rgb(var(--mode-accent-rgb) / 34%);
  border-radius: 14px;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 5%);
  font-size: 22px;
}

.mode-choice-copy {
  display: grid;
  min-width: 0;
  padding: 23px 24px 8px;
  grid-area: copy;
  align-content: start;
  gap: 8px;
}

.mode-choice-copy > strong {
  color: var(--text);
  font-size: 23px;
  line-height: 1.2;
}

.mode-choice-copy > small {
  min-height: 3.2em;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.6;
}

.mode-choice-fields {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.mode-choice-action {
  display: flex;
  padding: 10px 24px 22px;
  grid-area: action;
  align-items: center;
  justify-content: space-between;
  color: var(--mode-accent);
  font-size: 13px;
  font-weight: 850;
}

.mode-choice-action > span {
  font-size: 18px;
  line-height: 1;
  transition: transform 160ms ease;
}

.mode-choice-card:hover:not(:disabled) .mode-choice-action > span,
.mode-choice-card:focus-visible:not(:disabled) .mode-choice-action > span {
  transform: translateX(3px);
}

.flash-mode-editor {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
}

.flash-mode-gallery {
  display: grid;
  width: min(760px, 100%);
  min-height: 0;
  margin: auto;
  padding: clamp(28px, 5vw, 54px);
  overflow-y: auto;
  align-content: center;
  gap: 24px;
}

.flash-mode-heading {
  display: grid;
  gap: 8px;
}

.flash-mode-form,
.flash-tutorial-step {
  display: grid;
  gap: 16px;
}

.flash-onboarding {
  align-content: start;
}

.flash-progress {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.flash-progress span {
  padding: 8px 10px;
  color: var(--text-muted);
  text-align: center;
  background: var(--surface-soft);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.flash-progress span.active {
  color: var(--ci-on-primary);
  background: var(--primary);
  border-color: var(--primary);
}

.flash-progress span.complete {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 40%, var(--border));
}

.flash-source-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.flash-source-grid button,
.flash-character-results button {
  display: grid;
  min-width: 0;
  padding: 13px 14px;
  gap: 4px;
  color: var(--text-secondary);
  text-align: left;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  cursor: pointer;
}

.flash-source-grid button:hover,
.flash-source-grid button.active,
.flash-character-results button:hover {
  color: var(--text);
  background: var(--primary-soft);
  border-color: var(--primary-strong);
}

.flash-source-grid button strong,
.flash-character-results button strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.flash-source-grid button small,
.flash-character-results button small {
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.4;
}

.flash-source-panel,
.pro-current-chat-picker {
  display: grid;
  gap: 12px;
  padding: 14px;
  background: var(--surface-soft);
  border: 1px solid var(--border);
  border-radius: 12px;
}

.flash-character-results {
  display: grid;
  max-height: 260px;
  overflow-y: auto;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.flash-character-results p {
  grid-column: 1 / -1;
  margin: 0;
  padding: 14px;
  color: var(--text-muted);
  text-align: center;
  font-size: 11px;
}

.flash-mode-url-field {
  display: grid;
  gap: 7px;
}

.flash-mode-url-field > span,
.flash-target-note > span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
}

.flash-mode-url-field input,
.flash-mode-url-field select {
  width: 100%;
  min-height: 50px;
  padding: 11px 13px;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  outline: none;
}

.flash-mode-url-field input:focus,
.flash-mode-url-field select:focus {
  border-color: rgb(var(--ci-primary-rgb) / 68%);
  box-shadow: 0 0 0 3px rgb(var(--ci-primary-rgb) / 10%);
}

.flash-direct-link-tip {
  display: grid;
  gap: 6px;
  padding: 13px 14px;
  background: var(--primary-soft);
  border: 1px solid color-mix(in srgb, var(--primary) 28%, var(--border));
  border-radius: 12px;
}

.flash-direct-link-tip p,
.flash-direct-link-tip small {
  margin: 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.55;
}

.flash-image-preview {
  display: grid;
  min-height: 260px;
  overflow: hidden;
  place-items: center;
  color: var(--text-muted);
  background: var(--surface-soft);
  border: 1px dashed var(--border-strong);
  border-radius: 16px;
  text-align: center;
}

.flash-image-preview.ready {
  border-style: solid;
}

.flash-image-preview img {
  display: block;
  width: 100%;
  height: min(48vh, 420px);
  object-fit: contain;
}

.flash-step-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 4px;
}

.flash-step-actions > span {
  flex: 1;
}

.flash-confirm-card {
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr);
  gap: 14px;
  padding: 14px;
  align-items: center;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}

.flash-confirm-card img {
  width: 104px;
  height: 132px;
  object-fit: cover;
  border-radius: 10px;
}

.flash-confirm-card > div {
  display: grid;
  min-width: 0;
  gap: 5px;
}

.flash-confirm-card strong {
  overflow: hidden;
  color: var(--text);
  font-size: 20px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.flash-confirm-card span {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.flash-auto-checklist {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.flash-auto-checklist span {
  padding: 10px;
  color: var(--success);
  text-align: center;
  background: color-mix(in srgb, var(--success) 8%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--success) 28%, var(--border));
  border-radius: 10px;
  font-size: 11px;
  font-weight: 750;
}

.flash-save-feedback {
  padding: 12px 14px;
  background: var(--surface-soft);
  border-radius: 10px;
}

.pro-source-shortcuts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  margin-bottom: 16px;
}

.pro-source-shortcuts .secondary-button {
  width: 100%;
}

.target-divider {
  display: flex;
  margin: 18px 0 14px;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 800;
}

.target-divider::before,
.target-divider::after {
  height: 1px;
  flex: 1;
  content: '';
  background: var(--border);
}

.flash-target-note {
  display: grid;
  padding: 13px 14px;
  gap: 4px;
  background: var(--surface-soft);
  border-radius: 12px;
}

.flash-target-note strong {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.flash-mode-save-bar {
  display: flex;
  padding: 14px 22px max(14px, env(safe-area-inset-bottom, 0px));
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  background: var(--ci-header);
  border-top: 1px solid var(--border);
}

.flash-mode-save-bar .primary-button {
  min-width: 180px;
}

.flash-save-button {
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.flash-save-button.save-success,
.flash-save-button.save-success:disabled {
  color: var(--ci-on-primary);
  background: var(--success);
  border-color: var(--success);
  box-shadow: 0 8px 26px color-mix(in srgb, var(--success) 34%, transparent);
  opacity: 1;
  cursor: default;
  animation: flash-save-success-pop 560ms cubic-bezier(0.2, 0.85, 0.35, 1);
}

@keyframes flash-save-success-pop {
  0% {
    transform: scale(1);
  }
  42% {
    transform: scale(1.035);
  }
  100% {
    transform: scale(1);
  }
}

.target-panel,
.editor-panel {
  min-height: 0;
  overflow-y: auto;
}

.wizard-step-nav {
  display: flex;
  min-height: 0;
  padding: 22px 16px 18px;
  overflow-y: auto;
  flex-direction: column;
  gap: 8px;
  background: color-mix(in srgb, var(--surface) 78%, transparent);
  border-right: 1px solid var(--border);
}

.wizard-nav-header {
  display: flex;
  margin-bottom: 7px;
  padding: 0 7px 12px;
  align-items: center;
  justify-content: space-between;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.wizard-nav-header strong {
  color: var(--primary);
}

.wizard-step-nav button {
  display: grid;
  width: 100%;
  min-height: 66px;
  padding: 10px;
  align-items: center;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 11px;
  color: var(--text-secondary);
  text-align: left;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 12px;
  cursor: pointer;
}

.wizard-step-nav button:hover:not(:disabled) {
  background: rgb(255 255 255 / 4%);
  border-color: var(--border);
}

.wizard-step-nav button.active {
  color: var(--text);
  background: linear-gradient(110deg, var(--primary-soft), rgb(var(--ci-primary-rgb) / 4%));
  border-color: rgb(var(--ci-primary-rgb) / 35%);
  box-shadow: inset 3px 0 0 var(--primary);
}

.wizard-step-index {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  color: var(--text-muted);
  background: var(--surface-soft);
  border: 1px solid var(--border);
  border-radius: 9px;
  font-size: 12px;
  font-weight: 900;
}

.wizard-step-nav button.active .wizard-step-index {
  color: var(--ci-on-primary);
  background: var(--primary);
  border-color: var(--primary);
}

.wizard-step-nav button.complete:not(.active) .wizard-step-index {
  color: var(--success);
  background: rgb(120 213 156 / 9%);
  border-color: rgb(120 213 156 / 30%);
}

.wizard-step-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.wizard-step-copy strong,
.wizard-step-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wizard-step-copy strong {
  font-size: 13px;
}

.wizard-step-copy small {
  color: var(--text-muted);
  font-size: 10px;
}

.wizard-step-short-label {
  display: none;
}

.wizard-nav-context {
  display: flex;
  margin-top: auto;
  padding: 13px;
  flex-direction: column;
  gap: 4px;
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: 12px;
}

.wizard-nav-context small,
.wizard-nav-context span {
  color: var(--text-muted);
  font-size: 10px;
}

.wizard-nav-context strong {
  overflow: hidden;
  color: var(--text);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mobile-section-toggle {
  display: none;
}

.wizard-step-section.is-collapsed {
  display: none;
}

.target-panel,
.editor-panel {
  grid-column: 2;
  grid-row: 1;
}

.target-panel {
  padding: 32px 40px 36px;
  background: transparent;
  border-right: 0;
}

.target-panel-content {
  width: min(100%, 820px);
  margin: 0 auto;
}

.editor-panel {
  padding: 0;
}

.editor-panel > .wizard-step-section {
  width: min(100%, 1520px);
  min-height: 100%;
  margin: 0 auto;
  padding: 32px 40px 0;
}

.wizard-step-actions {
  display: flex;
  margin-top: 30px;
  padding-top: 20px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid var(--border);
}

.wizard-step-actions > span {
  flex: 1;
}

.section-title-row,
.output-heading,
.save-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.save-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}

.step-label {
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h2 {
  margin: 0;
  font-size: 17px;
}

.section-title-row h2,
.section-heading h2,
.output-heading h2 {
  font-size: 22px;
}

.current-character,
.target-summary,
.safety-note {
  padding: 14px;
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: 12px;
}

.current-character {
  display: flex;
  margin: 18px 0;
  flex-direction: column;
  gap: 3px;
}

.current-character span {
  color: var(--text-muted);
  font-size: 11px;
}

.current-character strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.target-panel .field + .field {
  margin-top: 15px;
}

.field-label {
  display: flex;
  min-height: 18px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.field-label-main {
  justify-content: flex-start;
  gap: 4px;
}

.field-label-main b {
  flex: 0 0 auto;
  color: #ff5c65;
  font-size: 14px;
  line-height: 1;
}

.manager-root.char-info-theme-light .field-label-main b {
  color: #c61e3c;
}

.field-guidance.warning {
  color: var(--warning);
}

.field-label-with-info,
.metadata-heading-with-info {
  justify-content: flex-start;
}

.metadata-heading-with-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.manager-root :deep(.info-bubble) {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
}

.manager-root :deep(.info-bubble-button) {
  display: grid;
  width: 20px;
  height: 20px;
  padding: 0;
  place-items: center;
  color: var(--text-muted);
  background: color-mix(in srgb, var(--surface-soft) 78%, transparent);
  border: 1px solid var(--border);
  border-radius: 50%;
  font-size: 12px;
  line-height: 1;
  cursor: help;
}

.manager-root :deep(.info-bubble-button:hover),
.manager-root :deep(.info-bubble-button:focus-visible) {
  color: var(--primary);
  border-color: color-mix(in srgb, var(--primary) 48%, var(--border));
  outline: none;
}

.manager-root :deep(.info-bubble-panel) {
  position: absolute;
  z-index: 40;
  top: calc(100% + 7px);
  left: 0;
  width: min(330px, calc(100vw - 56px));
  padding: 10px 11px;
  visibility: hidden;
  color: var(--text-secondary);
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  box-shadow: 0 12px 34px rgb(0 0 0 / 32%);
  font-size: 11px;
  font-weight: 550;
  line-height: 1.55;
  opacity: 0;
  transform: translateY(-3px);
  transition:
    opacity 120ms ease,
    transform 120ms ease,
    visibility 120ms ease;
  pointer-events: none;
}

.manager-root :deep(.info-bubble:hover .info-bubble-panel),
.manager-root :deep(.info-bubble:focus-within .info-bubble-panel) {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
}

.field-guidance {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}

.metadata-editor-panel {
  margin-top: 22px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface-raised) 74%, transparent);
}

.presentation-editor-panel > .field {
  margin-top: 12px;
}

.story-editor-panel {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.metadata-editor-heading,
.story-editor-heading,
.story-section-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.metadata-editor-heading h3,
.story-editor-heading h4 {
  margin: 0;
  font-size: 15px;
}

.metadata-editor-heading p,
.story-editor-heading p,
.story-editor-empty {
  margin: 5px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.metadata-field-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 16px;
}

.author-metadata-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.avatar-source-panel {
  display: grid;
  gap: 14px;
  margin-bottom: 18px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface-raised) 74%, transparent);
}

.avatar-source-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.avatar-source-option {
  display: flex;
  min-height: 64px;
  padding: 12px 13px;
  align-items: flex-start;
  gap: 10px;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--surface);
  cursor: pointer;
}

.avatar-source-option.active {
  border-color: var(--primary-strong);
  background: var(--primary-soft);
}

.avatar-source-option input {
  width: 18px;
  height: 18px;
  margin: 2px 0 0;
  padding: 0;
  accent-color: var(--primary-strong);
}

.avatar-source-option span {
  display: grid;
  gap: 3px;
}

.avatar-source-option strong {
  color: var(--text-secondary);
  font-size: 12px;
}

.avatar-source-option small {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}

.avatar-gallery-picker,
.avatar-custom-url {
  max-width: 620px;
}

.story-section-list {
  display: grid;
  gap: 14px;
  margin-top: 16px;
}

.story-section-card {
  display: grid;
  gap: 13px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-raised);
}

.story-section-card-header strong {
  color: var(--text-secondary);
  font-size: 12px;
}

.story-section-actions {
  display: flex;
  gap: 6px;
}

.story-section-actions button {
  width: 34px;
  min-height: 34px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text-secondary);
  cursor: pointer;
}

.story-section-actions button:hover:not(:disabled) {
  border-color: var(--primary-strong);
  color: var(--text);
}

.story-section-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

.story-section-actions button.danger {
  color: var(--danger);
}

.story-section-card textarea {
  min-height: 132px;
}

input,
select,
textarea {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  color: var(--text);
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: none;
}

textarea {
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--primary-strong);
  box-shadow: 0 0 0 3px var(--primary-soft);
}

.entry-combobox {
  position: relative;
}

.entry-combobox > input {
  padding-right: 44px;
}

.entry-picker-button {
  position: absolute;
  top: 2px;
  right: 2px;
  display: grid;
  width: 40px;
  height: 40px;
  padding: 0;
  place-items: center;
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}

.entry-options {
  position: absolute;
  z-index: 10;
  top: calc(100% + 7px);
  right: 0;
  left: 0;
  max-height: min(42vh, 360px);
  padding: 6px;
  overflow-y: auto;
  overscroll-behavior: contain;
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: 11px;
  box-shadow: 0 18px 44px rgb(0 0 0 / 48%);
}

.entry-options button {
  display: flex;
  width: 100%;
  min-height: 44px;
  padding: 9px 10px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}

.entry-options button:hover,
.entry-options button.highlighted,
.entry-options button[aria-selected='true'] {
  background: var(--primary-soft);
}

.entry-options button[aria-selected='true'] {
  color: var(--primary);
}

.entry-options button span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.entry-options button small {
  flex: 0 0 auto;
  padding: 2px 5px;
  color: var(--warning);
  background: rgb(244 195 106 / 10%);
  border-radius: 5px;
  font-size: 9px;
}

.entry-empty {
  margin: 0;
  padding: 18px 10px;
  color: var(--text-muted);
  text-align: center;
  font-size: 12px;
}

button:disabled,
input:disabled,
select:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.target-summary {
  display: flex;
  margin-top: 18px;
  align-items: flex-start;
  gap: 10px;
}

.target-summary p,
.safety-note p,
.section-heading p,
.output-heading p {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 12px;
}

.status-dot {
  flex: 0 0 auto;
  width: 9px;
  height: 9px;
  margin-top: 5px;
  background: var(--text-muted);
  border-radius: 50%;
}

.status-dot.managed {
  background: var(--success);
  box-shadow: 0 0 10px rgb(120 213 156 / 55%);
}

.status-dot.new {
  background: var(--primary);
}

.status-dot.blocked {
  background: var(--danger);
}

.status-dot.legacy-importable {
  background: var(--primary);
  box-shadow: 0 0 10px rgb(var(--ci-primary-rgb) / 45%);
}

.migration-banner {
  margin-top: 14px;
  padding: 12px 14px;
  border: 1px solid rgb(var(--ci-primary-rgb) / 24%);
  border-radius: 10px;
  background: rgb(var(--ci-primary-rgb) / 7%);
}

.migration-banner strong {
  color: var(--primary);
  font-size: 12px;
}

.migration-banner p,
.migration-banner ul {
  margin: 6px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
}

.migration-banner ul {
  padding-left: 18px;
}

.safety-note {
  margin-top: 16px;
  border-color: rgb(var(--ci-primary-rgb) / 22%);
}

.safety-note strong {
  color: var(--primary);
  font-size: 12px;
}

.message.error,
.save-feedback .error {
  color: var(--danger);
}

.form-section + .form-section,
.output-section {
  margin-top: 0;
  padding-top: 32px;
  border-top: 0;
}

.section-heading {
  display: flex;
  margin-bottom: 17px;
  align-items: flex-start;
  gap: 12px;
}

.step-number {
  display: grid;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  place-items: center;
  color: var(--ci-on-primary);
  background: var(--primary);
  border-radius: 9px;
  font-size: 12px;
  font-weight: 900;
}

.section-heading p {
  margin-top: 2px;
}

code {
  color: var(--primary);
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
}

.field-grid,
.color-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.field-full {
  grid-column: 1 / -1;
}

.color-custom-toggle {
  display: flex;
  min-height: 58px;
  margin-bottom: 14px;
  padding: 11px 13px;
  align-items: center;
  gap: 11px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 11px;
  cursor: pointer;
}

.color-custom-toggle input {
  width: 19px;
  min-height: 19px;
  height: 19px;
  margin: 0;
  padding: 0;
  accent-color: var(--primary-strong);
}

.color-custom-toggle span {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.color-custom-toggle strong {
  color: var(--text-secondary);
  font-size: 12px;
}

.color-custom-toggle small {
  color: var(--text-muted);
  font-size: 11px;
}

.color-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.color-control {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 9px;
}

.color-control input[type='color'] {
  padding: 5px;
  cursor: pointer;
}

.gallery-storage-panel {
  display: grid;
  gap: 12px;
  margin-bottom: 12px;
  padding: 13px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-soft);
}

.gallery-storage-toggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
}

.gallery-storage-toggle input {
  width: 18px;
  height: 18px;
  margin-top: 2px;
  accent-color: var(--primary);
}

.gallery-storage-toggle span {
  display: grid;
  gap: 3px;
}

.gallery-storage-toggle strong {
  color: var(--text-secondary);
  font-size: 12px;
}

.gallery-storage-toggle small,
.gallery-storage-message {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.gallery-storage-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.gallery-storage-fields .field-full {
  grid-column: 1 / -1;
}

.gallery-storage-message {
  margin: 0;
}

.gallery-storage-errors {
  margin: 0;
  padding: 10px 12px 10px 30px;
  border: 1px solid color-mix(in srgb, #ef8585 48%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, #ef8585 9%, transparent);
  color: #f2a2a2;
  font-size: 11px;
  line-height: 1.55;
}

.image-host-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
}

.image-host-links > div {
  display: grid;
  flex: 1 1 260px;
  gap: 2px;
}

.image-host-links strong {
  color: var(--text);
  font-size: 0.82rem;
}

.image-host-links small {
  color: var(--muted);
  font-size: 0.7rem;
}

.image-host-links a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  padding: 7px 11px;
  border: 1px solid var(--border-strong);
  border-radius: 9px;
  color: var(--primary);
  font-size: 0.75rem;
  text-decoration: none;
}

.image-host-links a:hover,
.image-host-links a:focus-visible {
  border-color: var(--primary);
  background: var(--primary-soft);
}

.gallery-list {
  display: grid;
  gap: 12px;
}

.gallery-card {
  display: grid;
  padding: 12px;
  grid-template-columns: 92px minmax(0, 1fr) auto;
  gap: 13px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 13px;
}

.image-preview {
  position: relative;
  display: grid;
  min-height: 104px;
  overflow: hidden;
  place-items: center;
  color: var(--text-muted);
  background: var(--surface-soft);
  border-radius: 9px;
}

.image-preview img,
.image-preview video {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 104px;
  object-fit: cover;
}

.image-preview video {
  pointer-events: none;
}

.image-preview .gallery-media-kind {
  position: absolute;
  right: 6px;
  bottom: 6px;
  padding: 3px 6px;
  color: var(--text);
  background: var(--ci-header);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
}

.image-preview b {
  position: absolute;
  top: 6px;
  left: 6px;
  padding: 3px 6px;
  color: var(--ci-on-primary);
  background: var(--primary);
  border-radius: 999px;
  font-size: 9px;
}

.image-preview .gallery-location-badge {
  color: var(--text);
  background: var(--ci-header);
}

.image-preview .gallery-location-badge.is-extension {
  color: var(--ci-on-primary);
  background: var(--primary);
}

.gallery-fields {
  display: grid;
  grid-template-columns: minmax(140px, 0.42fr) minmax(220px, 1fr);
  gap: 10px;
}

.source-list {
  display: grid;
  gap: 9px;
}

.source-input-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
}

.source-order-actions {
  display: flex;
  gap: 5px;
}

.source-order-button,
.remove-source-button,
.add-source-button {
  color: var(--text-secondary);
  background: var(--surface-soft);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
}

.source-order-button,
.remove-source-button {
  width: 34px;
  min-height: 42px;
}

.source-order-button:disabled,
.remove-source-button:disabled {
  opacity: 0.45;
  cursor: default;
}

.remove-source-button {
  color: var(--danger);
}

.add-source-button {
  min-height: 36px;
  padding: 7px 10px;
  justify-self: start;
  color: var(--primary);
}

.gallery-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.gallery-actions button {
  width: 38px;
  height: 32px;
  background: var(--surface-soft);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
}

.gallery-actions .danger {
  color: var(--danger);
}

.add-image-button,
.secondary-button,
.primary-button {
  min-height: 42px;
  padding: 9px 15px;
  border-radius: 10px;
  font-weight: 800;
  cursor: pointer;
}

.add-image-button {
  width: 100%;
  margin-top: 11px;
  color: var(--primary);
  background: transparent;
  border: 1px dashed var(--border-strong);
}

.secondary-button {
  background: var(--surface-soft);
  border: 1px solid var(--border);
}

.primary-button {
  color: var(--ci-on-primary);
  background: var(--primary);
  border: 1px solid var(--primary);
}

.primary-button:hover:not(:disabled),
.add-image-button:hover {
  background: var(--primary-strong);
}

.output-section {
  padding-bottom: 20px;
}

.output-heading p {
  margin-top: 1px;
}

details {
  margin-top: 12px;
  overflow: hidden;
  background: var(--ci-input);
  border: 1px solid var(--border);
  border-radius: 11px;
}

summary {
  padding: 11px 13px;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
}

pre {
  max-height: 280px;
  margin: 0;
  padding: 14px;
  overflow: auto;
  color: var(--text-secondary);
  border-top: 1px solid var(--border);
  font:
    11px/1.65 ui-monospace,
    SFMono-Regular,
    Consolas,
    monospace;
  white-space: pre;
}

.gallery-pack-download-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  margin-top: 14px;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: linear-gradient(120deg, var(--primary-soft), rgb(255 255 255 / 2%));
}

.gallery-pack-download-panel h3,
.gallery-pack-download-panel p {
  margin: 0;
}

.gallery-pack-download-panel h3 {
  margin-top: 3px;
  font-size: 15px;
}

.gallery-pack-download-panel p {
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.6;
}

.gallery-pack-download-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}

.gallery-pack-download-status,
.gallery-pack-download-message {
  grid-column: 1 / -1;
  margin: 0 !important;
  border-radius: 8px;
  padding: 9px 11px;
  font-weight: 700;
}

.gallery-pack-download-status {
  border: 1px solid color-mix(in srgb, var(--primary) 35%, transparent);
  background: color-mix(in srgb, var(--primary) 9%, transparent);
  color: var(--primary) !important;
}

.gallery-pack-download-status.error {
  border: 1px solid color-mix(in srgb, #ef8585 48%, transparent);
  background: color-mix(in srgb, #ef8585 9%, transparent);
  color: #f2a2a2 !important;
}

.gallery-pack-download-message {
  color: var(--primary) !important;
}

.save-bar {
  position: sticky;
  bottom: 0;
  margin: 28px -40px 0;
  padding: 15px 40px;
  background: var(--ci-header);
  border-top: 1px solid var(--border);
  backdrop-filter: blur(14px);
}

.save-feedback {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
  color: var(--text-muted);
  font-size: 11px;
}

.save-feedback strong {
  overflow: hidden;
  color: var(--text-secondary);
  text-overflow: ellipsis;
}

.save-feedback .success {
  color: var(--success);
}

@media (max-width: 900px) {
  .manager-root {
    padding: 10px;
    overflow: hidden;
  }
  .gallery-pack-download-panel {
    grid-template-columns: 1fr;
  }

  .gallery-pack-download-actions {
    justify-content: flex-start;
  }

  .manager-dialog {
    height: calc(100% - 2px);
    max-height: calc(100% - 2px);
    border-radius: 14px;
  }

  .dialog-header {
    padding: 17px;
  }

  .profile-editor-viewer-preview {
    inset: 0;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    max-width: none;
    max-height: none;
    box-sizing: border-box;
    transform: none;
    border: 0;
    border-radius: 0;
  }

  .profile-editor-viewer-preview-header {
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
    padding: calc(12px + var(--ci-mobile-safe-top)) calc(14px + var(--ci-mobile-safe-right)) 12px calc(14px + var(--ci-mobile-safe-left));
  }

  .profile-editor-viewer-preview-toolbar {
    display: grid;
    width: 100%;
    grid-template-columns: minmax(0, 1fr) minmax(126px, auto) 40px;
    gap: 8px;
  }

  .profile-editor-viewer-preview-source-state {
    min-width: 0;
    text-align: left;
  }

  .profile-editor-viewer-preview-source-toggle {
    min-width: 0;
    max-width: 164px;
    white-space: normal;
  }

  .profile-editor-viewer-preview-stage {
    padding: 0;
    overflow-x: hidden;
    overflow-y: auto;
    align-items: flex-start;
    justify-content: flex-start;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
  }

  .profile-editor-viewer-preview-frame,
  .profile-editor-viewer-preview-canvas {
    max-width: 100%;
  }

  .phase-badge {
    display: none;
  }

  .dialog-body {
    display: block;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
  }

  .dialog-body.mode-selection-body,
  .dialog-body.flash-mode {
    display: flex;
    overflow: hidden;
  }

  .mode-selection {
    width: 100%;
    margin: 0;
    padding: 24px 18px calc(28px + var(--ci-mobile-safe-bottom));
    align-content: start;
    gap: 22px;
    -webkit-overflow-scrolling: touch;
  }

  .mode-choice-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .mode-choice-card {
    min-height: 168px;
    padding: 0;
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 0;
  }

  .mode-choice-stub {
    padding: 14px 8px;
    gap: 9px;
  }

  .mode-choice-ticket-label {
    font-size: 8px;
  }

  .mode-choice-icon {
    width: 42px;
    height: 42px;
    font-size: 20px;
  }

  .mode-choice-copy {
    padding: 18px 17px 6px;
    gap: 6px;
  }

  .mode-choice-copy > strong {
    font-size: 20px;
  }

  .mode-choice-copy > small {
    min-height: 0;
    font-size: 12.5px;
    line-height: 1.55;
  }

  .mode-choice-fields {
    font-size: 10px;
  }

  .mode-choice-action {
    padding: 8px 17px 18px;
  }

  .flash-mode-editor {
    min-height: 0;
    height: 100%;
    flex: 1 1 auto;
  }

  .flash-mode-gallery {
    width: 100%;
    min-height: 0;
    margin: 0;
    padding: 24px 18px 20px;
    overflow-y: auto;
    align-content: start;
    flex: 1 1 auto;
    -webkit-overflow-scrolling: touch;
  }

  .flash-source-grid,
  .flash-character-results,
  .flash-auto-checklist,
  .pro-source-shortcuts {
    grid-template-columns: 1fr;
  }

  .flash-character-results {
    max-height: 220px;
  }

  .flash-image-preview {
    min-height: 220px;
  }

  .flash-image-preview img {
