  props.onOpenLibraryList();
}

function beginFloatingButtonDrag(event: PointerEvent): void {
  if (event.button !== 0) return;
  const button = event.currentTarget as HTMLButtonElement;
  const rect = button.getBoundingClientRect();
  floatingButtonDrag.pointerId = event.pointerId;
  floatingButtonDrag.startX = event.clientX;
  floatingButtonDrag.startY = event.clientY;
  floatingButtonDrag.originLeft = rect.left;
  floatingButtonDrag.originTop = rect.top;
  floatingButtonDrag.moved = false;
  dragPosition.value = { left: rect.left, top: rect.top };
  button.setPointerCapture(event.pointerId);
}

function moveFloatingButton(event: PointerEvent): void {
  if (floatingButtonDrag.pointerId !== event.pointerId) return;
  const deltaX = event.clientX - floatingButtonDrag.startX;
  const deltaY = event.clientY - floatingButtonDrag.startY;
  if (Math.hypot(deltaX, deltaY) > 4) floatingButtonDrag.moved = true;
  dragPosition.value = clampFloatingButtonPosition({
    left: floatingButtonDrag.originLeft + deltaX,
    top: floatingButtonDrag.originTop + deltaY,
  });
  if (floatingButtonDrag.moved) event.preventDefault();
}

function finishFloatingButtonDrag(event: PointerEvent, save: boolean): void {
  if (floatingButtonDrag.pointerId !== event.pointerId) return;
  const button = event.currentTarget as HTMLButtonElement;
  if (button.hasPointerCapture(event.pointerId)) button.releasePointerCapture(event.pointerId);
  floatingButtonDrag.pointerId = -1;
  if (save && floatingButtonDrag.moved && dragPosition.value) {
    props.onMoveLibraryButton(dragPosition.value);
    floatingButtonDrag.suppressClick = true;
  }
  dragPosition.value = null;
}

function endFloatingButtonDrag(event: PointerEvent): void {
  finishFloatingButtonDrag(event, true);
}

function cancelFloatingButtonDrag(event: PointerEvent): void {
  finishFloatingButtonDrag(event, false);
}

function keepFloatingButtonInViewport(): void {
  const position = props.state.library?.floatingButtonPosition;
  if (!position) return;
  const clamped = clampFloatingButtonPosition(position);
  if (clamped.left !== position.left || clamped.top !== position.top) props.onMoveLibraryButton(clamped);
}

function clampViewerWindowPosition(position: { left: number; top: number }): { left: number; top: number } {
  const viewport = getHostViewport();
  const windowElement = viewerWindowRef.value;
  const width = windowElement?.offsetWidth ?? Math.min(1100, viewport.width - 24);
  const height = windowElement?.offsetHeight ?? Math.min(820, viewport.height - 24);
  const margin = 6;
  return {
    left: Math.min(Math.max(margin, position.left), Math.max(margin, viewport.width - width - margin)),
    top: Math.min(Math.max(margin, position.top), Math.max(margin, viewport.height - height - margin)),
  };
}

const viewerWindowStyle = computed<CSSProperties>(() => {
  const position = viewerWindowPosition.value;
  return position ? { left: `${position.left}px`, top: `${position.top}px`, transform: 'none' } : {};
});

function beginViewerWindowDrag(event: PointerEvent): void {
  if (event.button !== 0 || (event.target as HTMLElement).closest('button')) return;
  const header = event.currentTarget as HTMLElement;
  const windowElement = viewerWindowRef.value;
  if (!windowElement) return;
  const rect = windowElement.getBoundingClientRect();
  viewerWindowDrag.pointerId = event.pointerId;
  viewerWindowDrag.startX = event.clientX;
  viewerWindowDrag.startY = event.clientY;
  viewerWindowDrag.originLeft = rect.left;
  viewerWindowDrag.originTop = rect.top;
  viewerWindowPosition.value = { left: rect.left, top: rect.top };
  header.setPointerCapture(event.pointerId);
}

function moveViewerWindow(event: PointerEvent): void {
  if (viewerWindowDrag.pointerId !== event.pointerId) return;
  viewerWindowPosition.value = clampViewerWindowPosition({
    left: viewerWindowDrag.originLeft + event.clientX - viewerWindowDrag.startX,
    top: viewerWindowDrag.originTop + event.clientY - viewerWindowDrag.startY,
  });
  event.preventDefault();
}

function finishViewerWindowDrag(event: PointerEvent): void {
  if (viewerWindowDrag.pointerId !== event.pointerId) return;
  const header = event.currentTarget as HTMLElement;
  if (header.hasPointerCapture(event.pointerId)) header.releasePointerCapture(event.pointerId);
  viewerWindowDrag.pointerId = -1;
}

function endViewerWindowDrag(event: PointerEvent): void {
  finishViewerWindowDrag(event);
}

function cancelViewerWindowDrag(event: PointerEvent): void {
  finishViewerWindowDrag(event);
}

function keepViewerWindowInViewport(): void {
  if (!viewerWindowPosition.value) return;
  viewerWindowPosition.value = clampViewerWindowPosition(viewerWindowPosition.value);
}

function keepFloatingUiInViewport(): void {
  keepFloatingButtonInViewport();
  keepViewerWindowInViewport();
}

function replaceSettingsDraft(settings: CharInfoUiSettings): void {
  floorLimitDraft.value = settings.activeFloorLimit;
  maxCardsPerMessageDraft.value = settings.maxCardsPerMessage;
  effectsEnabledDraft.value = settings.effectsEnabled;
  forceMobileLayoutDraft.value = settings.forceMobileLayout;
  themeModeDraft.value = settings.themeMode;
  fontSizeAdjustmentDraft.value = settings.fontSizeAdjustment;
  debugEnabledDraft.value = settings.debugEnabled;
  collapseModeEnabledDraft.value = settings.collapseModeEnabled;
  alwaysExpandRulesDraft.value = editableCollapseRules(settings.alwaysExpandRules);
  autoCollapseRulesDraft.value = editableCollapseRules(settings.autoCollapseRules);
  levelGapCollapseEnabledDraft.value = settings.levelGapCollapseEnabled;
  levelGapCollapseThresholdDraft.value = settings.levelGapCollapseThreshold;
  imageSourcePriorityEnabledDraft.value = settings.imageSourcePriorityEnabled;
  imageSourcePriorityDraft.value = [...settings.imageSourcePriority];
  useBaiBaiDraft.value = settings.portraitProvider === 'baibai';
  autoGeneratePortraitsDraft.value = settings.autoGeneratePortraits;
  portraitRewriteInstructionsDraft.value = settings.portraitRewriteInstructions;
  portraitOptionsDraft.value = { ...settings.portraitOptions };
  autoUpdateEnabledDraft.value = settings.autoUpdateEnabled;
}

function restorePortraitRewriteInstructions() {
  portraitRewriteInstructionsDraft.value = DEFAULT_PORTRAIT_REWRITE_INSTRUCTIONS;
  const { independentApi, profileId, apiSource, apiUrl, apiKey, apiModel } = portraitOptionsDraft.value;
  portraitOptionsDraft.value = PortraitOptionsSchema.parse({ independentApi, profileId, apiSource, apiUrl, apiKey, apiModel });
  applySettings();
}

function applySettings(): void {
  const priorityNormalization = normalizeImageSourcePriorityEntries(imageSourcePriorityDraft.value);
  const settings = props.onUpdateSettings({
    activeFloorLimit: Number(floorLimitDraft.value),
    maxCardsPerMessage: Number(maxCardsPerMessageDraft.value),
    unlimitedCardsPerMessage: Number(maxCardsPerMessageDraft.value) === 0,
    effectsEnabled: effectsEnabledDraft.value,
    forceMobileLayout: forceMobileLayoutDraft.value,
    themeMode: themeModeDraft.value,
    fontSizeAdjustment: Number(fontSizeAdjustmentDraft.value),
    debugEnabled: debugEnabledDraft.value,
    collapseModeEnabled: collapseModeEnabledDraft.value,
    alwaysExpandRules: alwaysExpandRulesDraft.value,
    autoCollapseRules: autoCollapseRulesDraft.value,
    levelGapCollapseEnabled: levelGapCollapseEnabledDraft.value,
    levelGapCollapseThreshold: Number(levelGapCollapseThresholdDraft.value),
    imageSourcePriorityEnabled: imageSourcePriorityEnabledDraft.value,
    imageSourcePriority: priorityNormalization.priorities,
    portraitProvider: useBaiBaiDraft.value ? 'baibai' : 'none',
    autoGeneratePortraits: autoGeneratePortraitsDraft.value,
    portraitRewriteInstructions: portraitRewriteInstructionsDraft.value,
    portraitOptions: portraitOptionsDraft.value,
    autoUpdateEnabled: autoUpdateEnabledDraft.value,
  });
  replaceSettingsDraft(settings);
  settingsMessage.value = priorityNormalization.rejectedCount
    ? `设置已保存；已忽略 ${priorityNormalization.rejectedCount} 条无效图片源规则。`
    : '设置已保存并立即应用。';
}

function toggleImageSourcePriority(): void {
  if (imageSourcePriorityEnabledDraft.value && imageSourcePriorityDraft.value.length === 0) {
    imageSourcePriorityDraft.value = [...DEFAULT_IMAGE_SOURCE_PRIORITY];
  }
  applySettings();
}

function addImageSourcePriority(): void {
  imageSourcePriorityDraft.value.push('');
  settingsMessage.value = '请填写图片网站域名，离开输入框后会自动保存。';
}

function useRecommendedImageSourcePriority(): void {
  imageSourcePriorityDraft.value = [...DEFAULT_IMAGE_SOURCE_PRIORITY];
  applySettings();
}

function moveImageSourcePriority(index: number, offset: -1 | 1): void {
  const targetIndex = index + offset;
  if (targetIndex < 0 || targetIndex >= imageSourcePriorityDraft.value.length) return;
  const priorities = [...imageSourcePriorityDraft.value];
  [priorities[index], priorities[targetIndex]] = [priorities[targetIndex], priorities[index]];
  imageSourcePriorityDraft.value = priorities;
  applySettings();
}

function removeImageSourcePriority(index: number): void {
  imageSourcePriorityDraft.value.splice(index, 1);
  applySettings();
}

function resetSettings(): void {
  replaceSettingsDraft(props.onResetSettings());
  settingsMessage.value = '已恢复默认设置。';
}

function diagnosticStatusLabel(status: DiagnosticStatus): string {
  if (status === 'pass') return '正常';
  if (status === 'warn') return '注意';
  if (status === 'fail') return '异常';
  return '信息';
}

async function runDiagnostics(): Promise<void> {
  if (diagnosticRunning.value) return;
  diagnosticRunning.value = true;
  diagnosticError.value = '';
  diagnosticReport.value = null;

  try {
    const loadedMessageIds = Array.from(window.parent.document.querySelectorAll<HTMLElement>('#chat > .mes'))
      .map(element => Number(element.getAttribute('mesid')))
      .filter(Number.isInteger)
      .sort((left, right) => left - right);
    const activeMessageIds = new Set(selectRecentMessageIds(loadedMessageIds, props.state.settings.activeFloorLimit));

    let candidate: { messageId: number; message: ChatMessage; swipeId: number } | null = null;
    for (const messageId of [...loadedMessageIds].reverse()) {
      const message = getChatMessages(messageId)[0];
      if (!message || message.role !== 'assistant' || message.is_hidden || typeof message.message !== 'string') continue;
      if (!/<char_info\b|<\/char_info\s*>/i.test(message.message)) continue;
      const swipeMessage = getChatMessages(messageId, { include_swipes: true })[0];
      const swipeId = swipeMessage && 'swipe_id' in swipeMessage ? swipeMessage.swipe_id : 0;
      candidate = { messageId, message, swipeId };
      break;
    }

    if (!candidate) {
      diagnosticError.value = '当前已加载聊天中没有找到包含 <char_info> 的 assistant 消息。';
      return;
    }

    const rawVariables = getVariables({ type: 'chat' });
    const chatVariables =
      rawVariables && typeof rawVariables === 'object' && !Array.isArray(rawVariables)
        ? (rawVariables as Record<string, unknown>)
        : {};

    diagnosticReport.value = await runCharInfoDiagnostics({
      messageId: candidate.messageId,
      swipeId: candidate.swipeId,
      text: candidate.message.message,
      maxCards: props.state.settings.unlimitedCardsPerMessage
        ? Number.MAX_SAFE_INTEGER
        : props.state.settings.maxCardsPerMessage,
      active: activeMessageIds.has(candidate.messageId),
      mounted: props.state.messages.some(message => message.messageId === candidate!.messageId),
      chatVariables,
      generatedPortraits: new Map(Array.from(storyPortraitViews.value, ([key, portrait]) => [key, portrait?.url ?? ''])),
      mountDiagnostics: props.state.mountDiagnostics,
    });
  } catch (error) {
    diagnosticError.value = `诊断失败：${error instanceof Error ? error.message : String(error)}`;
  } finally {
    diagnosticRunning.value = false;
  }
}

const filteredCharacters = computed(() => {
  const library = props.state.library;
  if (!library) return [];

  const query = searchText.value.toLocaleLowerCase('zh-Hans-CN');
  return library.characters.filter(character => {
    if (activeFilter.value === 'present' && !character.inScene) return false;
    if (activeFilter.value === 'away' && character.inScene) return false;
    if (!query) return true;
    return [character.name, character.race, character.identity].some(value =>
      value.toLocaleLowerCase('zh-Hans-CN').includes(query),
    );
  });
});

const activeFilterLabel = computed(
  () => filterOptions.find(option => option.value === activeFilter.value)?.label ?? '全部',
);
const libraryCharacterCount = computed(() => props.state.library?.characters.length ?? 0);

const selectedCharacter = computed(() => {
  const library = props.state.library;
  if (!library) return null;
  return (
    library.characters.find(character => character.name === selectedCharacterName.value) ??
    filteredCharacters.value[0] ??
    null
  );
});

const selectedPortrait = computed(() => {
  void props.state.portraitRevision;
  return props.portraits.libraryView(selectedCharacter.value ?? undefined, getVariables({ type: 'chat' }));
});

const selectedCharacterYaml = computed(() => {
  if (!selectedCharacter.value) return '';
  return dump(buildCurrentCharacterViewerData(selectedCharacter.value), {
    noRefs: true,
    lineWidth: 120,
    sortKeys: false,
  });
});

watch(
  () => props.state.library?.characters,
  characters => {
    if (!characters?.some(character => character.name === selectedCharacterName.value)) {
      selectedCharacterName.value = characters?.[0]?.name ?? '';
    }
  },
  { immediate: true },
);

watch(
  () => props.state.library,
  library => {
    searchText.value = '';
    activeFilter.value = 'all';
    selectedCharacterName.value = library?.characters[0]?.name ?? '';
  },
);

watch(
  () => Boolean(props.state.library?.listOpen && !props.state.library.viewerOpen && !props.state.library.worldbookOpen),
  listOpen => {
    if (!listOpen) innerThoughtInboxOpen.value = false;
  },
);

watch([innerThoughtInboxOpen, unreadThoughtCount], ([open, unread]) => {
  if (open && unread) props.onReadInnerThoughtInbox();
});

watch(
  () => props.state.settingsView,
  settingsView => {
    if (!settingsView) return;
    activeSettingsSection.value = 'library';
    replaceSettingsDraft(props.state.settings);
    settingsMessage.value = '';
  },
);

watch(activeFilter, () => {
  if (!filteredCharacters.value.some(character => character.name === selectedCharacterName.value)) {
    selectedCharacterName.value = filteredCharacters.value[0]?.name ?? '';
  }
});

onMounted(() => {
  const hostWindow = window.parent;
  hostWindow.addEventListener('resize', keepFloatingUiInViewport);
  hostWindow.visualViewport?.addEventListener('resize', keepFloatingUiInViewport);
  keepFloatingUiInViewport();
});

onBeforeUnmount(() => {
  const hostWindow = window.parent;
  hostWindow.removeEventListener('resize', keepFloatingUiInViewport);
  hostWindow.visualViewport?.removeEventListener('resize', keepFloatingUiInViewport);
});

