<template>
  <template v-for="message in state.messages" :key="message.messageId">
    <Teleport v-for="card in message.cards" :key="card.key" :to="card.host">
      <div
        class="char-info-runtime-message"
        :data-char-info-message-id="message.messageId"
        :data-char-info-render-key="card.renderKey"
      >
        <ViewerApp
          :key="`${card.renderKey}:${state.visualRevision}`"
          :yaml-text="card.yamlText"
          :message-id="message.messageId"
          :effects-enabled="state.settings.effectsEnabled"
          :force-mobile-layout="state.settings.forceMobileLayout"
          :font-size-adjustment="state.settings.fontSizeAdjustment"
          :debug-enabled="state.settings.debugEnabled"
          :image-source-priority="activeImageSourcePriority"
          :collapse-mode-enabled="state.settings.collapseModeEnabled"
          :always-expand-rules="state.settings.alwaysExpandRules"
          :auto-collapse-rules="state.settings.autoCollapseRules"
          :level-gap-collapse-enabled="state.settings.levelGapCollapseEnabled"
          :level-gap-collapse-threshold="state.settings.levelGapCollapseThreshold"
          :player-level="readPlayerLevel(message.messageId)"
          :generated-portrait-url="storyPortraitViews.get(card.key)?.url"
          :on-generated-portrait-load-error="() => reportPortraitLoadError(storyPortraitViews.get(card.key)?.target)"
          :save-state="state.saveStateByCard[card.key]"
          :save-feedback="feedback => props.saveFeedbackHandler(card.key, feedback)"
          embedded
        >
          <template #portrait-actions="{ authored }">
            <PortraitControls
              v-if="portraitControlsEnabled && !authored && storyPortraitViews.get(card.key)"
              :key="storyPortraitViews.get(card.key)!.target.key"
              :target="storyPortraitViews.get(card.key)!.target"
              :job="portraitJobsByKey.get(storyPortraitViews.get(card.key)!.target.key)"
              :previous-request="portraitRequestsByImage.get(storyPortraitViews.get(card.key)!.url)"
              :image-url="storyPortraitViews.get(card.key)!.url"
              :availability="state.portraitAvailability"
              :active-format="state.portraitFormat"
              :prepare-prompt="portraits.preparePrompt"
              @prepare="portraits.updateAvailability"
              @submit="(description, prompt) => portraits.submit(storyPortraitViews.get(card.key)!.target, description, prompt)"
            />
          </template>
        </ViewerApp>
      </div>
    </Teleport>
  </template>

  <Teleport v-if="state.library" :to="state.library.host">
    <button
      v-if="!characterLibraryOpen"
      class="char-info-library-floating-button"
      :class="managerThemeClass(state.settings.themeMode)"
      type="button"
      :style="floatingButtonStyle"
      :aria-label="floatingButtonAriaLabel"
      @click="openLibraryFromFloatingButton"
      @pointerdown="beginFloatingButtonDrag"
      @pointermove="moveFloatingButton"
      @pointerup="endFloatingButtonDrag"
      @pointercancel="cancelFloatingButtonDrag"
    >
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path
          d="M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm6.5-1a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM2 20.5c0-4 3.1-7 7-7s7 3 7 7v.5H2v-.5Zm13.2-7.1c3.8.3 6.8 3.2 6.8 7.1v.5h-4v-.5c0-2.8-1-5.2-2.8-7.1Z"
        />
      </svg>
      <span
        v-if="state.library.unreadCharacterNames.length"
        class="char-info-library-notification-dot"
        aria-hidden="true"
      ></span>
    </button>

    <div v-if="characterLibraryOpen" class="char-info-character-library-backdrop">
      <section
        ref="viewerWindowRef"
        class="char-info-library-overlay char-info-character-library"
        :class="[
          managerThemeClass(state.settings.themeMode),
          {
            'worldbook-mode': state.library.worldbookOpen,
            'force-mobile-layout': state.settings.forceMobileLayout,
          },
        ]"
        :style="viewerWindowStyle"
        role="dialog"
        aria-modal="false"
        aria-label="角色资料库"
      >
        <header
          class="char-info-character-library-header"
          @pointerdown="beginViewerWindowDrag"
          @pointermove="moveViewerWindow"
          @pointerup="endViewerWindowDrag"
          @pointercancel="cancelViewerWindowDrag"
        >
          <div class="char-info-character-library-title">
            <h2>角色资料库</h2>
            <div v-if="state.library.worldbookOpen" class="char-info-character-library-summary">
              <span>世界书角色</span>
              <span class="char-info-character-library-count" role="status">
                <strong>{{ worldbookLibrarySummary.filtered }}</strong>
                <span>{{ worldbookLibrarySummary.filtered === worldbookLibrarySummary.total ? '个角色' : `/ ${worldbookLibrarySummary.total} 个角色` }}</span>
              </span>
            </div>
            <p v-else>
              当前聊天角色 · 筛选：{{ activeFilterLabel }} · {{ filteredCharacters.length }}/{{ libraryCharacterCount }} 位角色
            </p>
          </div>

          <div class="char-info-library-source-switch char-info-character-library-switch" role="group" aria-label="角色资料来源">
            <button
              type="button"
              :class="{ active: !state.library.worldbookOpen }"
              :aria-pressed="!state.library.worldbookOpen"
              @click="props.onOpenCurrentChatLibrary"
            >
              当前聊天角色
            </button>
            <button
              type="button"
              :class="{ active: state.library.worldbookOpen }"
              :aria-pressed="state.library.worldbookOpen"
              @click="props.onOpenWorldbookLibrary"
            >
              世界书角色
            </button>
          </div>

          <div class="char-info-character-library-actions">
            <button
              class="char-info-character-library-edit-action"
              type="button"
              aria-label="编辑角色档案"
              title="编辑角色档案"
              @click="editCharacterProfileFromHeader"
            >
              <svg aria-hidden="true" viewBox="0 0 24 24">
                <path d="M4 19.5V15l10.8-10.8a2.1 2.1 0 0 1 3 0l2 2a2.1 2.1 0 0 1 0 3L9 20H4Z" />
                <path d="m13.5 5.5 5 5" />
              </svg>
            </button>
            <button class="char-info-character-library-settings-action" type="button" aria-label="查看器设置" title="设置" @click="onOpenSettings">
              <svg aria-hidden="true" viewBox="0 0 24 24">
                <path d="M12 8.5a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z" />
                <path
                  d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.42 1.42-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V20h-2v-.08A1.7 1.7 0 0 0 12.34 18a1.7 1.7 0 0 0-1.88.34l-.06.06-1.42-1.42.06-.06A1.7 1.7 0 0 0 9.38 15a1.7 1.7 0 0 0-1.56-1.03H7v-2h.82a1.7 1.7 0 0 0 1.56-1.03 1.7 1.7 0 0 0-.34-1.88L8.98 9l1.42-1.42.06.06a1.7 1.7 0 0 0 1.88.34A1.7 1.7 0 0 0 13.37 6.4V6h2v.4a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06L19.76 9l-.06.06a1.7 1.7 0 0 0-.34 1.88A1.7 1.7 0 0 0 20.92 12H21v2h-.08A1.7 1.7 0 0 0 19.4 15Z"
                />
              </svg>
            </button>
            <button type="button" aria-label="关闭角色资料库" @click="closeCharacterLibrary">×</button>
          </div>
        </header>

        <div class="char-info-character-library-body">
          <WorldbookCharacterLibrary
            v-if="state.library.worldbookOpen"
            embedded
            :force-mobile-layout="state.settings.forceMobileLayout"
            :theme-mode="state.settings.themeMode"
            @close="closeCharacterLibrary"
            @open-current-chat="onOpenCurrentChatLibrary"
            @selection-changed="worldbookName => (activeWorldbookEditorTarget = worldbookName)"
            @summary-changed="summary => (worldbookLibrarySummary = summary)"
            @edit="onEditWorldbookCharacter"
          />

          <template v-else>
            <div class="char-info-library-current-layout" :class="{ 'viewer-open': state.library.viewerOpen }">
              <div class="char-info-library-list-backdrop">
              <section
                class="char-info-library-list-dialog"
                :class="{ 'force-mobile-layout': state.settings.forceMobileLayout }"
                aria-label="当前聊天角色列表"
              >
        <div class="char-info-library-list-controls">
          <label>
            <span class="sr-only">搜索角色</span>
            <input ref="searchInputRef" v-model.trim="searchText" type="search" placeholder="搜索姓名、种族或身份" />
          </label>
          <div
            class="char-info-library-filters"
            role="group"
            aria-label="角色筛选"
          >
            <button
              v-for="option in filterOptions"
              :key="option.value"
              type="button"
              :class="{ active: activeFilter === option.value }"
              :aria-pressed="activeFilter === option.value"
              @click="activeFilter = option.value"
            >
              {{ option.label }}
            </button>
          </div>
        </div>

        <p v-if="state.library.error" class="char-info-library-error">{{ state.library.error }}</p>
        <p v-else-if="!state.library.loading && filteredCharacters.length === 0" class="char-info-library-empty">
          没有符合筛选条件的角色。
        </p>

        <div class="char-info-library-list">
          <button
            v-for="character in filteredCharacters"
            :key="character.name"
            type="button"
            :class="{
              active: selectedCharacterName === character.name,
              unread: state.library.unreadCharacterNames.includes(character.name),
            }"
            @click="openCharacter(character.name)"
          >
            <span class="char-info-library-avatar">
              <img
                v-if="character.avatarUrl && !failedAvatarUrls.has(character.avatarUrl)"
                :src="character.avatarUrl"
                :alt="`${character.name}头像`"
                loading="lazy"
                referrerpolicy="no-referrer"
                @error="onAvatarError(character.avatarUrl)"
              />
              <span v-else aria-hidden="true">{{ character.name.slice(0, 1) }}</span>
            </span>
            <span class="char-info-library-list-copy">
              <strong>{{ character.name }}</strong>
              <small>{{ [character.race, character.identity].filter(Boolean).join(' · ') || '资料待补全' }}</small>
            </span>
            <span class="char-info-library-list-meta">
              <span class="char-info-library-affinity">♡ {{ character.affinity ?? '—' }}</span>
              <span class="char-info-library-presence" :class="{ away: !character.inScene }">
                {{ character.inScene ? '在场' : '不在场' }}
              </span>
            </span>
            <span
              v-if="state.library.unreadCharacterNames.includes(character.name)"
              class="char-info-library-character-dot"
              aria-label="好感度有更新"
            ></span>
          </button>
        </div>

        <section
          v-show="innerThoughtInboxOpen"
          id="char-info-inner-thought-inbox"
          class="char-info-inner-thought-inbox"
          aria-labelledby="char-info-inner-thought-inbox-title"
        >
          <h3 id="char-info-inner-thought-inbox-title">心里话信箱</h3>
          <p v-if="!innerThoughtEntries.length">还没有新的心里话。</p>
          <ul v-else>
            <li v-for="entry in innerThoughtEntries" :key="entry.name">
              <span class="char-info-library-avatar">
                <img
                  v-if="entry.avatarUrl && !failedAvatarUrls.has(entry.avatarUrl)"
                  :src="entry.avatarUrl"
                  alt=""
                  loading="lazy"
                  referrerpolicy="no-referrer"
                  @error="onAvatarError(entry.avatarUrl)"
                />
                <span v-else aria-hidden="true">{{ entry.name.slice(0, 1) }}</span>
              </span>
              <div>
                <strong>{{ entry.name }}</strong>
                <p>{{ entry.text }}</p>
              </div>
            </li>
          </ul>
        </section>
        <nav class="char-info-library-mobile-dock" aria-label="角色资料库操作">
          <button type="button" aria-label="搜索角色" @click="focusLibrarySearch">
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <circle cx="11" cy="11" r="6.5" />
              <path d="m16 16 4 4" />
            </svg>
            <span>搜索</span>
          </button>
          <button
            type="button"
            class="char-info-inner-thought-inbox-button"
            :aria-label="unreadThoughtCount ? `信箱，${unreadThoughtCount} 条未读心里话` : '信箱'"
            aria-controls="char-info-inner-thought-inbox"
            :aria-expanded="innerThoughtInboxOpen"
            @click="innerThoughtInboxOpen = !innerThoughtInboxOpen"
          >
            <span class="char-info-inner-thought-inbox-icon" aria-hidden="true">
              <svg viewBox="0 0 24 24">
                <rect x="3" y="5" width="18" height="14" rx="2" />
                <path d="m4 7 8 6 8-6" />
              </svg>
              <span v-if="unreadThoughtCount" class="char-info-inner-thought-inbox-count">{{ unreadThoughtCount }}</span>
            </span>
            <span>信箱</span>
          </button>
          <button class="primary" type="button" aria-label="返回游戏并关闭角色资料库" @click="closeCharacterLibrary">
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <path d="m4 11 8-7 8 7" />
              <path d="M6.5 10v10h11V10M9.5 20v-6h5v6" />
            </svg>
            <span>返回游戏</span>
          </button>
          <button type="button" :disabled="state.library.loading" aria-label="刷新角色列表" @click="onRefreshLibrary">
            <svg :class="{ spinning: state.library.loading }" aria-hidden="true" viewBox="0 0 24 24">
              <path d="M20 11a8 8 0 1 0-2.34 5.66" />
              <path d="M20 5v6h-6" />
            </svg>
            <span>刷新</span>
          </button>
          <button type="button" aria-label="打开查看器设置" @click="onOpenSettings">
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <path d="M12 8.5a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z" />
              <path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.42 1.42-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V20h-2v-.08A1.7 1.7 0 0 0 12.34 18a1.7 1.7 0 0 0-1.88.34l-.06.06-1.42-1.42.06-.06A1.7 1.7 0 0 0 9.38 15a1.7 1.7 0 0 0-1.56-1.03H7v-2h.82a1.7 1.7 0 0 0 1.56-1.03 1.7 1.7 0 0 0-.34-1.88L8.98 9l1.42-1.42.06.06a1.7 1.7 0 0 0 1.88.34A1.7 1.7 0 0 0 13.37 6.4V6h2v.4a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06L19.76 9l-.06.06a1.7 1.7 0 0 0-.34 1.88A1.7 1.7 0 0 0 20.92 12H21v2h-.08A1.7 1.7 0 0 0 19.4 15Z" />
            </svg>
            <span>设置</span>
          </button>
        </nav>
      </section>
    </div>

              <section class="char-info-library-current-viewer" aria-label="当前聊天角色资料">
                <header class="char-info-library-header">
        <h2>{{ selectedCharacter?.name || '角色资料' }}</h2>
        <div class="char-info-library-header-actions">
          <button class="char-info-library-list-action" type="button" @click="onOpenLibraryList">
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <path d="M5 6h14M5 12h14M5 18h14" />
              <circle cx="3" cy="6" r="0.75" />
              <circle cx="3" cy="12" r="0.75" />
              <circle cx="3" cy="18" r="0.75" />
            </svg>
            <span>角色列表</span>
          </button>
          <button
            v-if="selectedCharacter"
            class="char-info-library-list-action char-info-library-profile-action"
            type="button"
            @click="props.onEditCurrentChatCharacterProfile(selectedCharacter.name)"
          >
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <path d="M4 19.5V15l10.8-10.8a2.1 2.1 0 0 1 3 0l2 2a2.1 2.1 0 0 1 0 3L9 20H4Z" />
              <path d="m13.5 5.5 5 5" />
            </svg>
            <span>{{ selectedCharacter.hasProfileRecord ? '编辑档案' : '添加档案' }}</span>
          </button>
          <button
            class="char-info-library-icon-action"
            type="button"
            :disabled="state.library.loading"
            :aria-label="state.library.loading ? '正在刷新角色资料' : '刷新角色资料'"
            @click="onRefreshLibrary"
          >
            <svg :class="{ spinning: state.library.loading }" aria-hidden="true" viewBox="0 0 24 24">
              <path d="M20 11a8 8 0 1 0-2.34 5.66" />
              <path d="M20 5v6h-6" />
            </svg>
          </button>
          <button
            class="char-info-library-icon-action char-info-library-close-action"
            type="button"
            aria-label="关闭角色资料"
            @click="closeCharacterLibrary"
          >
            <svg aria-hidden="true" viewBox="0 0 24 24">
              <path d="m7 7 10 10M17 7 7 17" />
            </svg>
          </button>
        </div>
      </header>

      <main class="char-info-library-viewer">
        <ViewerApp
          v-if="!state.library.viewerLoading && selectedCharacter && selectedCharacterYaml"
          :key="`${state.library.messageId}:${state.library.revision}:${selectedCharacter.name}`"
          :yaml-text="selectedCharacterYaml"
          :message-id="state.library.messageId"
          :effects-enabled="state.settings.effectsEnabled"
          :force-mobile-layout="state.settings.forceMobileLayout"
          :font-size-adjustment="state.settings.fontSizeAdjustment"
          :debug-enabled="state.settings.debugEnabled"
          :image-source-priority="activeImageSourcePriority"
          :entrance-quote-override="selectedCharacter.innerThought"
          :generated-portrait-url="selectedPortrait?.url"
          :on-generated-portrait-load-error="() => reportPortraitLoadError(selectedPortrait?.target)"
          embedded
          read-only
        >
          <template #portrait-actions="{ authored }">
            <PortraitControls
              v-if="portraitControlsEnabled && !authored && selectedPortrait"
              :key="selectedPortrait.target.key"
              :target="selectedPortrait.target"
              :job="portraitJobsByKey.get(selectedPortrait.target.key)"
              :previous-request="portraitRequestsByImage.get(selectedPortrait.url)"
              :image-url="selectedPortrait.url"
              :availability="state.portraitAvailability"
              :active-format="state.portraitFormat"
              :prepare-prompt="portraits.preparePrompt"
              @prepare="portraits.updateAvailability"
              @submit="(description, prompt) => selectedPortrait && portraits.submit(selectedPortrait.target, description, prompt)"
            />
          </template>
        </ViewerApp>
        <div v-else class="char-info-library-placeholder">
          <span aria-hidden="true">◇</span>
          <p>
            {{
              state.library.viewerLoading
                ? '正在准备最新角色资料…'
                : state.library.loading
                  ? '正在读取角色资料…'
                  : '暂时无法找到该角色的资料。'
            }}
          </p>
        </div>
      </main>

      <nav class="char-info-library-viewer-mobile-dock" aria-label="角色资料操作">
        <button class="viewer-dock-list" type="button" aria-label="返回角色列表" @click="showLibraryListFromViewer">
          <svg aria-hidden="true" viewBox="0 0 24 24">
            <path d="M5 6h14M5 12h14M5 18h14" />
            <circle cx="3" cy="6" r="0.75" />
            <circle cx="3" cy="12" r="0.75" />
            <circle cx="3" cy="18" r="0.75" />
          </svg>
          <span>角色列表</span>
        </button>
        <button class="primary viewer-dock-home" type="button" aria-label="返回游戏并关闭角色资料" @click="closeCharacterLibrary">
          <svg aria-hidden="true" viewBox="0 0 24 24">
            <path d="m4 11 8-7 8 7" />
            <path d="M6.5 10v10h11V10M9.5 20v-6h5v6" />
          </svg>
          <span>返回游戏</span>
        </button>
        <button
          v-if="selectedCharacter"
          class="viewer-dock-profile"
          type="button"
          :aria-label="selectedCharacter.hasProfileRecord ? '编辑角色档案' : '添加角色档案'"
          @click="props.onEditCurrentChatCharacterProfile(selectedCharacter.name)"
        >
          <svg aria-hidden="true" viewBox="0 0 24 24">
            <path d="M4 19.5V15l10.8-10.8a2.1 2.1 0 0 1 3 0l2 2a2.1 2.1 0 0 1 0 3L9 20H4Z" />
            <path d="m13.5 5.5 5 5" />
          </svg>
          <span>{{ selectedCharacter.hasProfileRecord ? '编辑档案' : '添加档案' }}</span>
        </button>
      </nav>
              </section>
            </div>
          </template>
        </div>
      </section>
    </div>
  </Teleport>

  <Teleport v-if="state.settingsView" :to="state.settingsView.host">
    <div
      class="char-info-settings-backdrop"
      :class="managerThemeClass(state.settings.themeMode)"
      @click.self="onCloseSettings"
    >
      <section
        class="char-info-settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="char-info-settings-title"
      >
        <header>
          <h2 id="char-info-settings-title">查看器设置</h2>
          <button type="button" aria-label="关闭查看器设置" @click="onCloseSettings">×</button>
        </header>

        <div class="char-info-settings-body">
          <nav class="char-info-settings-nav" aria-label="设置分类">
            <template v-for="section in settingsSections" :key="section.id">
            <span v-if="section.id === 'performance'" class="char-info-settings-nav-heading">查看器设定</span>
            <button
              type="button"
              :class="{ 'char-info-settings-nav-debug': section.id === 'diagnostics' }"
              :aria-current="activeSettingsSection === section.id ? 'true' : undefined"
              :aria-controls="settingsPanelId(section.id)"
              @click="selectSettingsSection(section.id)"
            >
              {{ section.label }}
            </button>
            </template>
          </nav>

          <div ref="settingsContent" class="char-info-settings-fields">
            <h3 id="char-info-settings-section-heading">{{ activeSettingsLabel }}</h3>

            <section
              v-show="activeSettingsSection === 'library'"
              :id="settingsPanelId('library')"
              class="char-info-settings-panel"
              aria-labelledby="char-info-settings-section-heading"
            >
              <div class="char-info-settings-rows">
                <label>
                  <span>
                    <strong>界面主题</strong>
                  </span>
                  <select v-model="themeModeDraft" @change="applySettings">
                    <option value="dark">深色</option>
                    <option value="light">浅色</option>
                  </select>
                </label>
              </div>

              <section class="char-info-settings-priority" aria-labelledby="char-info-image-source-priority-label">
                <label class="char-info-settings-switch char-info-settings-priority-switch">
